function ArchivedReportFooter({report, reportClosedAction, personalDetails = {}}: ArchivedReportFooterProps) {
    const styles = useThemeStyles();
    const {translate} = useLocalize();

    const originalMessage = ReportActionsUtils.isClosedAction(reportClosedAction) ? ReportActionsUtils.getOriginalMessage(reportClosedAction) : null;
    const archiveReason = originalMessage?.reason ?? CONST.REPORT.ARCHIVE_REASON.DEFAULT;
    const actorPersonalDetails = personalDetails?.[reportClosedAction?.actorAccountID ?? -1];
    let displayName = PersonalDetailsUtils.getDisplayNameOrDefault(actorPersonalDetails);

    let oldDisplayName: string | undefined;
    if (archiveReason === CONST.REPORT.ARCHIVE_REASON.ACCOUNT_MERGED) {
        const newAccountID = originalMessage?.newAccountID;
        const oldAccountID = originalMessage?.oldAccountID;
        displayName = PersonalDetailsUtils.getDisplayNameOrDefault(personalDetails?.[newAccountID ?? -1]);
        oldDisplayName = PersonalDetailsUtils.getDisplayNameOrDefault(personalDetails?.[oldAccountID ?? -1]);
    }

    const shouldRenderHTML = archiveReason !== CONST.REPORT.ARCHIVE_REASON.DEFAULT && archiveReason !== CONST.REPORT.ARCHIVE_REASON.BOOKING_END_DATE_HAS_PASSED;

    let policyName = ReportUtils.getPolicyName(report);

    if (archiveReason === CONST.REPORT.ARCHIVE_REASON.INVOICE_RECEIVER_POLICY_DELETED) {
        policyName = originalMessage?.receiverPolicyName ?? '';
    }

    if (shouldRenderHTML) {
        oldDisplayName = lodashEscape(oldDisplayName);
        displayName = lodashEscape(displayName);
        policyName = lodashEscape(policyName);
    }

    const text = shouldRenderHTML
        ? translate(`reportArchiveReasons.${archiveReason}`, {
              displayName: `<strong>${displayName}</strong>`,
              oldDisplayName: `<strong>${oldDisplayName}</strong>`,
              policyName: `<strong>${policyName}</strong>`,
              shouldUseYou: actorPersonalDetails?.accountID === getCurrentUserAccountID(),
          })
        : translate(`reportArchiveReasons.${archiveReason}`);

    return (
        <Banner
            containerStyles={[styles.chatFooterBanner]}
            text={text}
            shouldRenderHTML={shouldRenderHTML}
            shouldShowIcon
        />
    );
}

function LocaleContextProvider({preferredLocale, currentUserPersonalDetails, children}: LocaleContextProviderProps) {
    const locale = preferredLocale ?? CONST.LOCALES.DEFAULT;

    const selectedTimezone = useMemo(() => currentUserPersonalDetails?.timezone?.selected, [currentUserPersonalDetails]);

    const translate = useMemo<LocaleContextProps['translate']>(
        () =>
            (path, ...parameters) =>
                Localize.translate(locale, path, ...parameters),
        [locale],
    );

    const numberFormat = useMemo<LocaleContextProps['numberFormat']>(() => (number, options) => NumberFormatUtils.format(locale, number, options), [locale]);

    const datetimeToRelative = useMemo<LocaleContextProps['datetimeToRelative']>(() => (datetime) => DateUtils.datetimeToRelative(locale, datetime), [locale]);

    const datetimeToCalendarTime = useMemo<LocaleContextProps['datetimeToCalendarTime']>(
        () =>
            (datetime, includeTimezone, isLowercase = false) =>
                DateUtils.datetimeToCalendarTime(locale, datetime, includeTimezone, selectedTimezone, isLowercase),
        [locale, selectedTimezone],
    );

    const updateLocale = useMemo<LocaleContextProps['updateLocale']>(() => () => DateUtils.setLocale(locale), [locale]);

    const formatPhoneNumber = useMemo<LocaleContextProps['formatPhoneNumber']>(() => (phoneNumber) => LocalePhoneNumber.formatPhoneNumber(phoneNumber), []);

    const toLocaleDigit = useMemo<LocaleContextProps['toLocaleDigit']>(() => (digit) => LocaleDigitUtils.toLocaleDigit(locale, digit), [locale]);

    const toLocaleOrdinal = useMemo<LocaleContextProps['toLocaleOrdinal']>(
        () =>
            (number, writtenOrdinals = false) =>
                LocaleDigitUtils.toLocaleOrdinal(locale, number, writtenOrdinals),
        [locale],
    );

    const fromLocaleDigit = useMemo<LocaleContextProps['fromLocaleDigit']>(() => (localeDigit) => LocaleDigitUtils.fromLocaleDigit(locale, localeDigit), [locale]);

    const contextValue = useMemo<LocaleContextProps>(
        () => ({
            translate,
            numberFormat,
            datetimeToRelative,
            datetimeToCalendarTime,
            updateLocale,
            formatPhoneNumber,
            toLocaleDigit,
            toLocaleOrdinal,
            fromLocaleDigit,
            preferredLocale: locale,
        }),
        [translate, numberFormat, datetimeToRelative, datetimeToCalendarTime, updateLocale, formatPhoneNumber, toLocaleDigit, toLocaleOrdinal, fromLocaleDigit, locale],
    );

    return <LocaleContext.Provider value={contextValue}>{children}</LocaleContext.Provider>;
}

function findColumnName(header: string): string {
    let attribute = '';
    const formattedHeader = Str.removeSpaces(String(header).toLowerCase().trim());
    switch (formattedHeader) {
        case 'email':
        case 'emailaddress':
        case 'emailaddresses':
        case 'e-mail':
        case 'e-mailaddress':
        case 'e-mailaddresses':
            attribute = CONST.CSV_IMPORT_COLUMNS.EMAIL;
            break;

        case 'category':
        case 'categories':
            attribute = CONST.CSV_IMPORT_COLUMNS.EMAIL;
            break;

        case 'glcode':
        case 'gl':
            attribute = CONST.CSV_IMPORT_COLUMNS.GL_CODE;
            break;

        case 'tag':
        case 'tags':
        case 'project':
        case 'projectcode':
        case 'customer':
        case 'name':
            attribute = 'name';
            break;

        case 'submitto':
        case 'submitsto':
            attribute = CONST.CSV_IMPORT_COLUMNS.SUBMIT_TO;
            break;

        case 'approveto':
        case 'approvesto':
            attribute = CONST.CSV_IMPORT_COLUMNS.APPROVE_TO;
            break;

        case 'payroll':
        case 'payrollid':
        case 'payrolls':
        case 'payrol':
        case 'customfield2':
            attribute = CONST.CSV_IMPORT_COLUMNS.CUSTOM_FIELD_2;
            break;

        case 'userid':
        case 'customfield1':
            attribute = CONST.CSV_IMPORT_COLUMNS.CUSTOM_FIELD_1;
            break;

        case 'role':
            attribute = CONST.CSV_IMPORT_COLUMNS.ROLE;
            break;

        case 'total':
        case 'threshold':
        case 'reporttotal':
        case 'reporttotalthreshold':
        case 'approvallimit':
            attribute = CONST.CSV_IMPORT_COLUMNS.REPORT_THRESHHOLD;
            break;

        case 'alternate':
        case 'alternateapprove':
        case 'alternateapproveto':
        case 'overlimitforwardsto':
            attribute = CONST.CSV_IMPORT_COLUMNS.APPROVE_TO_ALTERNATE;

            break;

        case 'destination':
            attribute = CONST.CSV_IMPORT_COLUMNS.NAME;
            break;

        case 'subrate':
            attribute = CONST.CSV_IMPORT_COLUMNS.SUBRATE;
            break;

        case 'amount':
            attribute = CONST.CSV_IMPORT_COLUMNS.AMOUNT;
            break;

        case 'currency':
            attribute = CONST.CSV_IMPORT_COLUMNS.CURRENCY;
            break;

        case 'rateid':
            attribute = CONST.CSV_IMPORT_COLUMNS.RATE_ID;
            break;

        case 'enabled':
        case 'enable':
            attribute = CONST.CSV_IMPORT_COLUMNS.ENABLED;
            break;

        default:
            break;
    }

    return attribute;
}

function ImportColumn({column, columnName, columnRoles, columnIndex}: ImportColumnProps) {
    const styles = useThemeStyles();
    const {translate} = useLocalize();
    const [spreadsheet] = useOnyx(ONYXKEYS.IMPORTED_SPREADSHEET);
    const {containsHeader = true} = spreadsheet ?? {};

    const options: Array<DropdownOption<string>> = columnRoles.map((item) => ({
        text: item.text,
        value: item.value,
        description: item.description ?? (item.isRequired ? translate('common.required') : undefined),
        isSelected: spreadsheet?.columns?.[columnIndex] === item.value,
    }));

    const columnValuesString = column.slice(containsHeader ? 1 : 0).join(', ');

    const colName = findColumnName(column[0]);
    const defaultSelectedIndex = columnRoles.findIndex((item) => item.value === colName);

    useEffect(() => {
        if (defaultSelectedIndex === -1) {
            return;
        }
        setColumnName(columnIndex, colName);
        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps -- we don't want this effect to run again
    }, []);

    const columnHeader = containsHeader ? column[0] : translate('spreadsheet.column', {name: columnName});

    return (
        <View style={[styles.importColumnCard, styles.mt4]}>
            <Text
                numberOfLines={1}
                style={[styles.textSupporting, styles.mw100]}
            >
                {columnHeader}
            </Text>
            <View style={[styles.flexRow, styles.alignItemsCenter, styles.mt2]}>
                <Text
                    numberOfLines={2}
                    ellipsizeMode="tail"
                    style={[styles.flex1, styles.flexWrap, styles.breakAll]}
                >
                    {columnValuesString}
                </Text>

                <View style={styles.ml2}>
                    <ButtonWithDropdownMenu
                        onPress={() => {}}
                        buttonSize={CONST.DROPDOWN_BUTTON_SIZE.SMALL}
                        shouldShowSelectedItemCheck
                        menuHeaderText={columnHeader}
                        isSplitButton={false}
                        onOptionSelected={(option) => {
                            setColumnName(columnIndex, option.value);
                        }}
                        defaultSelectedIndex={defaultSelectedIndex}
                        options={options}
                    />
                </View>
            </View>
        </View>
    );
}

