                <PressableWithoutFeedback
                    onPress={onRightIconPress}
                    style={[styles.touchableButtonImage]}
                    role={CONST.ROLE.BUTTON}
                    accessibilityLabel={rightIconAccessibilityLabel}
                >
                    <Icon
                        src={rightIcon}
                        fill={theme.icon}
                    />
                </PressableWithoutFeedback>
            ) : (
