        return (
            !!brickRoadIndicator && (
                <Icon
                    src={Expensicons.DotIndicator}
                    fill={brickRoadIndicator === CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR ? theme.danger : theme.success}
