function callOrReturn<TArgs extends unknown[], TReturn>(value: TReturn | Func<TArgs, TReturn>, ...args: TArgs): TReturn {
    if (typeof value === 'function') {
        return (value as Func<TArgs, TReturn>)(...args);
    }

    return value;
}

function isLoadingOnyxValue(...results: ResultMetadata[]): boolean {
    return results.some((result) => result.status === 'loading');
}

function isEmptyObject<T>(obj: T | EmptyValue): obj is EmptyValue {
    return Object.keys(obj ?? {}).length === 0;
}

function isValidOnyxUpdateFromServer(value: unknown): value is OnyxUpdatesFromServer {
    if (!value || typeof value !== 'object') {
        return false;
    }
    if (!('type' in value) || !value.type) {
        return false;
    }
    if (value.type === CONST.ONYX_UPDATE_TYPES.HTTPS) {
        if (!('request' in value) || !value.request) {
            return false;
        }

        if (!('response' in value) || !value.response) {
            return false;
        }
    }
    if (value.type === CONST.ONYX_UPDATE_TYPES.PUSHER) {
        if (!('updates' in value) || !value.updates) {
            return false;
        }
    }

    return true;
}

