function beforeRemoveReportOpenedFromSearchRHP(event: EventArg<'beforeRemove', true>) {
    if (!navigationRef.current) {
        return;
    }

    const state = navigationRef.current?.getRootState() as State<RootStackParamList>;

    if (!state) {
        return;
    }

    const shouldPopHome =
        state.routes?.length >= 3 &&
        state.routes.at(-1)?.name === SCREENS.REPORT &&
        state.routes.at(-2)?.name === NAVIGATORS.RIGHT_MODAL_NAVIGATOR &&
        getTopmostBottomTabRoute(state)?.name === SCREENS.HOME;

    if (!shouldPopHome) {
        return;
    }

    event.preventDefault();
    const bottomTabState = state?.routes?.at(0)?.state;
    navigationRef.dispatch({...StackActions.pop(), target: bottomTabState?.key});
    Navigation.goBack();
}

function createModalStackNavigator<TStackParams extends ParamListBase>(screens: Screens, getScreenOptions?: (styles: ThemeStyles) => StackNavigationOptions): React.ComponentType {
    const ModalStackNavigator = createStackNavigator<TStackParams>();

    function ModalStack() {
        const screenOptions = useModalScreenOptions(getScreenOptions);

        return (
            <ModalStackNavigator.Navigator screenOptions={screenOptions}>
                {Object.keys(screens as Required<Screens>).map((name) => (
                    <ModalStackNavigator.Screen
                        key={name}
                        name={name}
                        getComponent={(screens as Required<Screens>)[name as Screen]}
                    />
                ))}
            </ModalStackNavigator.Navigator>
        );
    }

    ModalStack.displayName = 'ModalStack';

    return ModalStack;
}

function ModalStack() {
        const screenOptions = useModalScreenOptions(getScreenOptions);

        return (
            <ModalStackNavigator.Navigator screenOptions={screenOptions}>
                {Object.keys(screens as Required<Screens>).map((name) => (
                    <ModalStackNavigator.Screen
                        key={name}
                        name={name}
                        getComponent={(screens as Required<Screens>)[name as Screen]}
